package com.netmonitor.pro;

import android.app.*;import android.content.*;import android.content.pm.*;import android.content.res.ColorStateList;import android.graphics.Color;import android.graphics.drawable.*;import android.net.VpnService;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;import java.text.*;import android.content.ClipData;

public class MainActivity extends Activity {
 static final int VPN_REQ=77; LinearLayout root,list; TextView status,stats,game; Button start; ArrayList<AppInfo> apps=new ArrayList<>();SharedPreferences prefs;int page=0;
 int dp(float x){return(int)(x*getResources().getDisplayMetrics().density+.5f);}
 GradientDrawable bg(String c,float r){GradientDrawable g=new GradientDrawable();g.setColor(Color.parseColor(c));g.setCornerRadius(dp(r));return g;}
 TextView tv(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextColor(Color.WHITE);t.setTextSize(z);t.setPadding(dp(12),dp(8),dp(12),dp(8));return t;}
 Button bt(String s){Button b=new Button(this);b.setText(s);b.setTextColor(Color.WHITE);b.setTextSize(13);b.setAllCaps(false);b.setBackground(bg("#202943",16));return b;}
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("apps",0);build();loadApps();update();}
 void build(){
  root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(12),dp(10),dp(12),dp(8));root.setBackgroundColor(Color.rgb(8,12,23));
  TextView title=tv("📡  NetMonitor Pro",23);title.setTypeface(null,1);root.addView(title);
  LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(12),dp(5),dp(12),dp(5));card.setBackground(bg("#111A2E",22));
  status=tv("⛔ غير نشط",16);stats=tv("🌐 IPs: 0   🔌 Ports: 0   📦 Packets: 0",14);game=tv("🎮 التطبيقات المحددة: 0",14);
  start=bt("🚀 بدء المراقبة");start.setOnClickListener(v->toggle());card.addView(status);card.addView(stats);card.addView(game);card.addView(start);root.addView(card,new LinearLayout.LayoutParams(-1,dp(170)));
  LinearLayout a=new LinearLayout(this);String[]x={"📱 التطبيقات","⚙️ الإعدادات","🗑 مسح","📤 CSV","📄 JSON"};for(String s:x){Button q=bt(s);a.addView(q,new LinearLayout.LayoutParams(0,dp(50),1));if(s.startsWith("📱"))q.setOnClickListener(v->chooseApps());else if(s.startsWith("⚙️"))q.setOnClickListener(v->settings());else if(s.startsWith("🗑"))q.setOnClickListener(v->{MonitorStore.clear();update();});else if(s.startsWith("📤"))q.setOnClickListener(v->share(export(false),"CSV"));else q.setOnClickListener(v->share(export(true),"JSON"));}root.addView(a);
  LinearLayout tabs=new LinearLayout(this);String[]ts={"📋 الاتصالات","🌐 IPs","🔌 المنافذ"};for(int i=0;i<3;i++){final int n=i;Button q=bt(ts[i]);q.setOnClickListener(v->{page=n;updateList();});tabs.addView(q,new LinearLayout.LayoutParams(0,dp(48),1));}root.addView(tabs);
  ScrollView sv=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);sv.addView(list);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);
  final Handler h=new Handler();h.postDelayed(new Runnable(){public void run(){update();h.postDelayed(this,700);}},700);
 }
 void loadApps(){PackageManager pm=getPackageManager();Intent i=new Intent(Intent.ACTION_MAIN);i.addCategory(Intent.CATEGORY_LAUNCHER);HashSet<String>s=new HashSet<>();for(ResolveInfo r:pm.queryIntentActivities(i,PackageManager.MATCH_ALL)){String p=r.activityInfo.packageName;if(s.add(p))apps.add(new AppInfo(r.loadLabel(pm).toString(),p,r.loadIcon(pm)));}Collections.sort(apps,(a,b)->a.label.compareToIgnoreCase(b.label));}
 ArrayList<String>selected(){ArrayList<String>s=new ArrayList<>();for(AppInfo a:apps)if(prefs.getBoolean(a.packageName,false))s.add(a.packageName);return s;}
 void chooseApps(){LinearLayout rows=new LinearLayout(this);rows.setOrientation(LinearLayout.VERTICAL);for(AppInfo a:apps){CheckBox c=new CheckBox(this);c.setText(a.label+"\n"+a.packageName);c.setTextColor(Color.WHITE);c.setTextSize(13);c.setChecked(prefs.getBoolean(a.packageName,false));c.setButtonTintList(new ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{Color.rgb(108,99,255),Color.GRAY}));rows.addView(c,new LinearLayout.LayoutParams(-1,dp(58)));c.setTag(a.packageName);}
  ScrollView sc=new ScrollView(this);sc.addView(rows);AlertDialog d=new AlertDialog.Builder(this).setTitle("📱 اختر التطبيقات").setMessage("فقط التطبيقات المحددة ستمر عبر VPN وتظهر اتصالاتها.").setView(sc).setNegativeButton("إلغاء",null).setPositiveButton("حفظ",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{for(int j=0;j<rows.getChildCount();j++){CheckBox c=(CheckBox)rows.getChildAt(j);prefs.edit().putBoolean((String)c.getTag(),c.isChecked()).apply();}d.dismiss();update();}));d.show();}
 void toggle(){if(MonitorVpnService.running()){stopService(new Intent(this,MonitorVpnService.class));update();return;}ArrayList<String>s=selected();if(s.isEmpty()){new AlertDialog.Builder(this).setTitle("اختر تطبيقاً").setMessage("اضغط 📱 التطبيقات وحدد تطبيقاً واحداً على الأقل.").setPositiveButton("حسناً",null).show();return;}Intent p=VpnService.prepare(this);if(p!=null)startActivityForResult(p,VPN_REQ);else startVpn(s);}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==VPN_REQ&&c==RESULT_OK)startVpn(selected());}
 void startVpn(ArrayList<String>s){Intent i=new Intent(this,MonitorVpnService.class);i.putStringArrayListExtra("apps",s);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}
 void update(){boolean on=MonitorVpnService.running();status.setText(on?"✅ جاري المراقبة...":"⛔ غير نشط");status.setTextColor(on?Color.rgb(70,230,150):Color.rgb(255,100,110));start.setText(on?"⏹ إيقاف المراقبة":"🚀 بدء المراقبة");stats.setText("🌐 IPs: "+MonitorStore.ips()+"   🔌 Ports: "+MonitorStore.ports()+"   📦 Packets: "+MonitorStore.packets());game.setText("🎮 التطبيقات المحددة: "+selected().size());updateList();}
 void updateList(){if(list==null)return;list.removeAllViews();List<ConnectionRecord>d=MonitorStore.all(); ArrayList<ConnectionRecord> filtered=new ArrayList<>(); int pmin=prefs.getInt("minPort",0), pmax=prefs.getInt("maxPort",65535); for(ConnectionRecord r:d) if(r.port>=pmin&&r.port<=pmax) filtered.add(r); d=filtered;if(page==1){LinkedHashSet<String>s=new LinkedHashSet<>();for(ConnectionRecord r:d)s.add(r.ip);for(String x:s)list.addView(tv("🌐 "+x,16));return;}if(page==2){LinkedHashSet<Integer>s=new LinkedHashSet<>();for(ConnectionRecord r:d)s.add(r.port);for(Integer x:s)list.addView(tv("🔌 "+x,16));return;}for(int i=d.size()-1;i>=0;i--){ConnectionRecord r=d.get(i);String tm=new SimpleDateFormat("HH:mm:ss",Locale.getDefault()).format(new Date(r.time));TextView t=tv((r.protocol.equals("UDP")?"🟢 ":"🔵 ")+r.protocol+"   "+r.ip+" : "+r.port+"   "+tm,14);t.setBackground(bg("#111A2E",14));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(48));p.setMargins(0,0,0,dp(4));list.addView(t,p);}}
 void settings(){
  LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(8),dp(4),dp(8),dp(4));
  CheckBox only=new CheckBox(this);only.setText("إظهار الاتصالات الخاصة بالتطبيقات المحددة فقط");only.setTextColor(Color.WHITE);only.setChecked(prefs.getBoolean("onlySelected",true));box.addView(only);
  LinearLayout row=new LinearLayout(this);
  EditText min=new EditText(this);min.setHint("الحد الأدنى للمنفذ");min.setInputType(2);min.setText(String.valueOf(prefs.getInt("minPort",0)));row.addView(min,new LinearLayout.LayoutParams(0,dp(55),1));
  EditText max=new EditText(this);max.setHint("الحد الأقصى للمنفذ");max.setInputType(2);max.setText(String.valueOf(prefs.getInt("maxPort",65535)));row.addView(max,new LinearLayout.LayoutParams(0,dp(55),1));box.addView(row);
  new AlertDialog.Builder(this).setTitle("⚙️ الإعدادات").setView(box).setNegativeButton("إلغاء",null).setPositiveButton("حفظ",(d,w)->{
    int a=0,b=65535;try{a=Integer.parseInt(min.getText().toString());}catch(Exception e){}try{b=Integer.parseInt(max.getText().toString());}catch(Exception e){}
    prefs.edit().putBoolean("onlySelected",only.isChecked()).putInt("minPort",Math.max(0,a)).putInt("maxPort",Math.min(65535,b)).apply();updateList();
  }).show();
 }
 String export(boolean json){List<ConnectionRecord>d=MonitorStore.all(); ArrayList<ConnectionRecord> filtered=new ArrayList<>(); int pmin=prefs.getInt("minPort",0), pmax=prefs.getInt("maxPort",65535); for(ConnectionRecord r:d) if(r.port>=pmin&&r.port<=pmax) filtered.add(r); d=filtered;StringBuilder s=new StringBuilder();if(!json){s.append("Time,Protocol,IP,Port,Bytes\n");for(ConnectionRecord r:d)s.append(r.time).append(',').append(r.protocol).append(',').append(r.ip).append(',').append(r.port).append(',').append(r.bytes).append('\n');}else{s.append("[\n");for(int i=0;i<d.size();i++){ConnectionRecord r=d.get(i);s.append("{\"time\":").append(r.time).append(",\"protocol\":\"").append(r.protocol).append("\",\"ip\":\"").append(r.ip).append("\",\"port\":").append(r.port).append(",\"bytes\":").append(r.bytes).append("}").append(i+1<d.size()?",":"").append('\n');}s.append("]");}return s.toString();}
 void share(String data,String type){Intent i=new Intent(Intent.ACTION_SEND);i.setType(type.equals("CSV")?"text/csv":"application/json");i.putExtra(Intent.EXTRA_TEXT,data);startActivity(Intent.createChooser(i,"مشاركة "+type));}
}